// Builds preload.bundle.js: preload.js plus electron-chrome-extensions' toolbar element in one file.
// The UI window is sandboxed, and a sandboxed preload can only require('electron'), so the library's
// browser-action module (which itself needs nothing but 'electron') is inlined. The output is
// committed; test/units.js checks it still matches this script's output. Run after changing
// preload.js or updating electron-chrome-extensions:  node scripts/bundle-preload.js
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const OUT = path.join(ROOT, 'src', 'preload', 'preload.bundle.js');
const INLINED = ['electron-chrome-extensions/browser-action'];

const read = (file) => fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n').replace(/^#!.*\n/, '');
const indent = (src) => src.trimEnd().split('\n').map((l) => (l ? `    ${l}` : l)).join('\n');

function bundle() {
  const modules = INLINED.map((id) => `  ${JSON.stringify(id)}: (module, exports, require) => {\n${indent(read(require.resolve(id, { paths: [ROOT] })))}\n  },`);
  return [
    '// Generated by scripts/bundle-preload.js from preload.js. Do not edit; edit preload.js and rerun it.',
    '(() => {',
    'const inlined = {',
    ...modules,
    '};',
    'const loaded = {};',
    'const load = (id) => {',
    '  if (!(id in inlined)) return require(id);',
    '  if (!loaded[id]) { const module = { exports: {} }; loaded[id] = module; inlined[id](module, module.exports, load); }',
    '  return loaded[id].exports;',
    '};',
    '((require) => {',
    read(path.join(ROOT, 'src', 'preload', 'preload.js')).trimEnd(),
    '})(load);',
    '})();',
    '',
  ].join('\n');
}

if (require.main === module) {
  fs.writeFileSync(OUT, bundle());
  console.log(`wrote ${path.relative(ROOT, OUT)}`);
}

module.exports = { bundle, OUT };
